CREATE TABLE IF NOT EXISTS "workspaces" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Workspace display name.
	"name" VARCHAR(120) NOT NULL,
	-- Subdomain used to sign in. Unique across the platform because it is part of the URL.
	"domain" VARCHAR(80) NOT NULL UNIQUE,
	-- free | pro | business | enterprise. Decides message retention and the app install limit.
	"plan_tier" VARCHAR(20) NOT NULL DEFAULT 'free',
	-- Channel every new member is auto-joined to. Null while the workspace is still being created.
	"default_channel_id" BIGINT,
	-- Days before messages are purged. Null means keep forever, which is the paid default.
	"message_retention_days" INTEGER,
	-- Workspace creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "workspaces" IS 'The tenancy boundary. Channels, memberships and app installs are all scoped to exactly one workspace; only the user account crosses that line.';
COMMENT ON COLUMN "workspaces"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "workspaces"."name" IS 'Workspace display name.';
COMMENT ON COLUMN "workspaces"."domain" IS 'Subdomain used to sign in. Unique across the platform because it is part of the URL.';
COMMENT ON COLUMN "workspaces"."plan_tier" IS 'free | pro | business | enterprise. Decides message retention and the app install limit.';
COMMENT ON COLUMN "workspaces"."default_channel_id" IS 'Channel every new member is auto-joined to. Null while the workspace is still being created.';
COMMENT ON COLUMN "workspaces"."message_retention_days" IS 'Days before messages are purged. Null means keep forever, which is the paid default.';
COMMENT ON COLUMN "workspaces"."created_at" IS 'Workspace creation time.';

CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key. The account is global so one person can be in many workspaces with one login.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity, unique platform-wide.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Real name as entered at signup.
	"full_name" VARCHAR(160) NOT NULL,
	-- CDN URL of the profile image.
	"avatar_url" VARCHAR(500),
	-- IANA timezone. Drives notification schedules and the "local time" shown on a profile.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- True for an app bot user. Bots post messages and hold memberships exactly like people.
	"is_bot" BOOLEAN NOT NULL DEFAULT false,
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A global account. Anything that differs per workspace - title, admin rights, display name - lives in workspace_members instead.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key. The account is global so one person can be in many workspaces with one login.';
COMMENT ON COLUMN "users"."email" IS 'Login identity, unique platform-wide.';
COMMENT ON COLUMN "users"."full_name" IS 'Real name as entered at signup.';
COMMENT ON COLUMN "users"."avatar_url" IS 'CDN URL of the profile image.';
COMMENT ON COLUMN "users"."timezone" IS 'IANA timezone. Drives notification schedules and the "local time" shown on a profile.';
COMMENT ON COLUMN "users"."is_bot" IS 'True for an app bot user. Bots post messages and hold memberships exactly like people.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "workspace_members" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Workspace joined.
	"workspace_id" BIGINT NOT NULL,
	-- Account joining it.
	"user_id" BIGINT NOT NULL,
	-- Per-workspace handle. The same person can be "ana" at work and "ana.r" in a community workspace.
	"display_name" VARCHAR(80) NOT NULL,
	-- Job title shown on the profile card inside this workspace.
	"title" VARCHAR(160),
	-- guest | member | admin | owner. Guests can only see channels they are explicitly invited to.
	"role" VARCHAR(20) NOT NULL DEFAULT 'member',
	-- Custom status line. Null when cleared.
	"status_text" VARCHAR(100),
	-- When the status auto-clears. Null means it persists until changed.
	"status_expires_at" TIMESTAMP,
	-- Deactivated members keep their messages and memberships; the row is never deleted or the history loses its author.
	"is_deactivated" BOOLEAN NOT NULL DEFAULT false,
	-- When the account joined this workspace.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "workspace_members" IS 'One row per account per workspace. Deactivation is a flag, never a delete, because every message and file in the workspace points back here.';
COMMENT ON COLUMN "workspace_members"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "workspace_members"."workspace_id" IS 'Workspace joined.';
COMMENT ON COLUMN "workspace_members"."user_id" IS 'Account joining it.';
COMMENT ON COLUMN "workspace_members"."display_name" IS 'Per-workspace handle. The same person can be "ana" at work and "ana.r" in a community workspace.';
COMMENT ON COLUMN "workspace_members"."title" IS 'Job title shown on the profile card inside this workspace.';
COMMENT ON COLUMN "workspace_members"."role" IS 'guest | member | admin | owner. Guests can only see channels they are explicitly invited to.';
COMMENT ON COLUMN "workspace_members"."status_text" IS 'Custom status line. Null when cleared.';
COMMENT ON COLUMN "workspace_members"."status_expires_at" IS 'When the status auto-clears. Null means it persists until changed.';
COMMENT ON COLUMN "workspace_members"."is_deactivated" IS 'Deactivated members keep their messages and memberships; the row is never deleted or the history loses its author.';
COMMENT ON COLUMN "workspace_members"."joined_at" IS 'When the account joined this workspace.';

CREATE UNIQUE INDEX "uq_workspace_members_ws_user"
ON "workspace_members" ("workspace_id", "user_id");
CREATE INDEX "idx_workspace_members_active"
ON "workspace_members" ("workspace_id", "is_deactivated");

CREATE TABLE IF NOT EXISTS "channels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning workspace. A shared channel is still owned by whichever workspace created it.
	"workspace_id" BIGINT NOT NULL,
	-- Channel name, lowercased and hyphenated. Unique within a workspace, not globally.
	"name" VARCHAR(80) NOT NULL,
	-- public | private | shared | dm | group_dm. A DM is a channel with no name shown and a fixed membership.
	"kind" VARCHAR(20) NOT NULL DEFAULT 'public',
	-- Short header line.
	"topic" VARCHAR(250),
	-- Longer description shown in the channel browser.
	"purpose" VARCHAR(250),
	-- Creator. Null once that membership is purged during an org migration.
	"created_by_member_id" BIGINT,
	-- Archived channels are read-only but fully searchable; archiving is not deletion.
	"is_archived" BOOLEAN NOT NULL DEFAULT false,
	-- How many other workspaces are connected. Non-zero is what makes a channel shared, and it is denormalised so the banner renders without a join.
	"external_workspace_count" SMALLINT NOT NULL DEFAULT 0,
	-- Newest message time. Null for an empty channel; drives sidebar ordering.
	"last_message_at" TIMESTAMP,
	-- Channel creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "channels" IS 'Every conversation is a channel, including DMs. One table means one membership model, one message table and one search path rather than a parallel set for direct messages.';
COMMENT ON COLUMN "channels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "channels"."workspace_id" IS 'Owning workspace. A shared channel is still owned by whichever workspace created it.';
COMMENT ON COLUMN "channels"."name" IS 'Channel name, lowercased and hyphenated. Unique within a workspace, not globally.';
COMMENT ON COLUMN "channels"."kind" IS 'public | private | shared | dm | group_dm. A DM is a channel with no name shown and a fixed membership.';
COMMENT ON COLUMN "channels"."topic" IS 'Short header line.';
COMMENT ON COLUMN "channels"."purpose" IS 'Longer description shown in the channel browser.';
COMMENT ON COLUMN "channels"."created_by_member_id" IS 'Creator. Null once that membership is purged during an org migration.';
COMMENT ON COLUMN "channels"."is_archived" IS 'Archived channels are read-only but fully searchable; archiving is not deletion.';
COMMENT ON COLUMN "channels"."external_workspace_count" IS 'How many other workspaces are connected. Non-zero is what makes a channel shared, and it is denormalised so the banner renders without a join.';
COMMENT ON COLUMN "channels"."last_message_at" IS 'Newest message time. Null for an empty channel; drives sidebar ordering.';
COMMENT ON COLUMN "channels"."created_at" IS 'Channel creation time.';

CREATE UNIQUE INDEX "uq_channels_workspace_name"
ON "channels" ("workspace_id", "name");
CREATE INDEX "idx_channels_workspace_kind"
ON "channels" ("workspace_id", "kind", "is_archived");

CREATE TABLE IF NOT EXISTS "channel_members" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel joined.
	"channel_id" BIGINT NOT NULL,
	-- Membership joining it, not the global user, so a guest in one workspace cannot inherit access in another.
	"workspace_member_id" BIGINT NOT NULL,
	-- The read cursor: the newest message this person has seen. Null means nothing read yet, so the whole channel is unread.
	"last_read_message_id" BIGINT,
	-- When the cursor last moved. Kept alongside the id for analytics and for resolving a cursor whose message was deleted.
	"last_read_at" TIMESTAMP,
	-- all | mentions | nothing. Overrides the workspace default for this channel only.
	"notification_level" VARCHAR(16) NOT NULL DEFAULT 'all',
	-- Suppresses the unread badge without leaving the channel.
	"is_muted" BOOLEAN NOT NULL DEFAULT false,
	-- Join time. Messages older than this still count as unread unless the cursor says otherwise.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "channel_members" IS 'Membership and the read cursor in one row. One row per person per channel is what bounds the write volume of read tracking, no matter how many messages the channel carries.';
COMMENT ON COLUMN "channel_members"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "channel_members"."channel_id" IS 'Channel joined.';
COMMENT ON COLUMN "channel_members"."workspace_member_id" IS 'Membership joining it, not the global user, so a guest in one workspace cannot inherit access in another.';
COMMENT ON COLUMN "channel_members"."last_read_message_id" IS 'The read cursor: the newest message this person has seen. Null means nothing read yet, so the whole channel is unread.';
COMMENT ON COLUMN "channel_members"."last_read_at" IS 'When the cursor last moved. Kept alongside the id for analytics and for resolving a cursor whose message was deleted.';
COMMENT ON COLUMN "channel_members"."notification_level" IS 'all | mentions | nothing. Overrides the workspace default for this channel only.';
COMMENT ON COLUMN "channel_members"."is_muted" IS 'Suppresses the unread badge without leaving the channel.';
COMMENT ON COLUMN "channel_members"."joined_at" IS 'Join time. Messages older than this still count as unread unless the cursor says otherwise.';

CREATE UNIQUE INDEX "uq_channel_members_channel_member"
ON "channel_members" ("channel_id", "workspace_member_id");
CREATE INDEX "idx_channel_members_member_channel"
ON "channel_members" ("workspace_member_id", "channel_id");

CREATE TABLE IF NOT EXISTS "messages" (
	-- Surrogate primary key, monotonic so comparing it to the read cursor is what computes unread counts.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel the message belongs to. Thread replies keep it too, so channel-level retention and search stay one scan.
	"channel_id" BIGINT NOT NULL,
	-- Author. Null for a system message such as a join or a channel rename.
	"workspace_member_id" BIGINT,
	-- App that posted, when a message came in through an integration rather than a person.
	"app_id" BIGINT,
	-- The thread parent. Null for a top-level message; non-null makes this a reply, which is the entire thread model.
	"parent_message_id" BIGINT,
	-- Message text in the rich-text markup. Null for a file-only or attachment-only post.
	"body" TEXT,
	-- A thread reply also sent to the channel. The flag exists so the channel view can include it without duplicating the row.
	"is_broadcast" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised replies, maintained on the parent so the "12 replies" affordance costs no aggregate.
	"reply_count" INTEGER NOT NULL DEFAULT 0,
	-- Send time.
	"sent_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit. Null means never edited.
	"edited_at" TIMESTAMP,
	-- Soft delete, so replies, saved items and read cursors pointing here do not dangle.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "messages" IS 'Top-level messages and thread replies in one table, distinguished only by parent_message_id. The (channel_id, id) index is the one the unread count relies on.';
COMMENT ON COLUMN "messages"."id" IS 'Surrogate primary key, monotonic so comparing it to the read cursor is what computes unread counts.';
COMMENT ON COLUMN "messages"."channel_id" IS 'Channel the message belongs to. Thread replies keep it too, so channel-level retention and search stay one scan.';
COMMENT ON COLUMN "messages"."workspace_member_id" IS 'Author. Null for a system message such as a join or a channel rename.';
COMMENT ON COLUMN "messages"."app_id" IS 'App that posted, when a message came in through an integration rather than a person.';
COMMENT ON COLUMN "messages"."parent_message_id" IS 'The thread parent. Null for a top-level message; non-null makes this a reply, which is the entire thread model.';
COMMENT ON COLUMN "messages"."body" IS 'Message text in the rich-text markup. Null for a file-only or attachment-only post.';
COMMENT ON COLUMN "messages"."is_broadcast" IS 'A thread reply also sent to the channel. The flag exists so the channel view can include it without duplicating the row.';
COMMENT ON COLUMN "messages"."reply_count" IS 'Denormalised replies, maintained on the parent so the "12 replies" affordance costs no aggregate.';
COMMENT ON COLUMN "messages"."sent_at" IS 'Send time.';
COMMENT ON COLUMN "messages"."edited_at" IS 'Last edit. Null means never edited.';
COMMENT ON COLUMN "messages"."deleted_at" IS 'Soft delete, so replies, saved items and read cursors pointing here do not dangle.';

CREATE INDEX "idx_messages_channel_id"
ON "messages" ("channel_id", "id");
CREATE INDEX "idx_messages_thread"
ON "messages" ("parent_message_id", "sent_at");
CREATE INDEX "idx_messages_author_sent"
ON "messages" ("workspace_member_id", "sent_at");

CREATE TABLE IF NOT EXISTS "mentions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Message containing the mention.
	"message_id" BIGINT NOT NULL,
	-- Person mentioned. Null for a broadcast mention such as @channel or @here.
	"workspace_member_id" BIGINT,
	-- user | channel | here | everyone | usergroup. Extracted once at write time, never parsed on read.
	"mention_type" VARCHAR(16) NOT NULL,
	-- Extraction time, which equals the send time of the message.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "mentions" IS 'Mentions are extracted into rows at write time. Without this table the "mentions and reactions" view and every mention-only notification rule would mean scanning message bodies.';
COMMENT ON COLUMN "mentions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "mentions"."message_id" IS 'Message containing the mention.';
COMMENT ON COLUMN "mentions"."workspace_member_id" IS 'Person mentioned. Null for a broadcast mention such as @channel or @here.';
COMMENT ON COLUMN "mentions"."mention_type" IS 'user | channel | here | everyone | usergroup. Extracted once at write time, never parsed on read.';
COMMENT ON COLUMN "mentions"."created_at" IS 'Extraction time, which equals the send time of the message.';

CREATE INDEX "idx_mentions_member_created"
ON "mentions" ("workspace_member_id", "created_at");
CREATE INDEX "idx_mentions_message"
ON "mentions" ("message_id");

CREATE TABLE IF NOT EXISTS "reactions" (
	-- Message reacted to, part of the composite key.
	"message_id" BIGINT,
	-- Who reacted, part of the composite key.
	"workspace_member_id" BIGINT,
	-- Emoji shortcode without colons, part of the key. The three columns are exactly the uniqueness rule.
	"emoji_name" VARCHAR(80),
	-- When it was added; the hover tooltip lists reactors in this order.
	"reacted_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("message_id", "workspace_member_id", "emoji_name")
);

COMMENT ON TABLE "reactions" IS 'Composite key, no surrogate id, and no stored counts - removing a reaction is as common as adding one, so the tally is aggregated.';
COMMENT ON COLUMN "reactions"."message_id" IS 'Message reacted to, part of the composite key.';
COMMENT ON COLUMN "reactions"."workspace_member_id" IS 'Who reacted, part of the composite key.';
COMMENT ON COLUMN "reactions"."emoji_name" IS 'Emoji shortcode without colons, part of the key. The three columns are exactly the uniqueness rule.';
COMMENT ON COLUMN "reactions"."reacted_at" IS 'When it was added; the hover tooltip lists reactors in this order.';

CREATE INDEX "idx_reactions_message_emoji"
ON "reactions" ("message_id", "emoji_name");

CREATE TABLE IF NOT EXISTS "files" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning workspace, so retention and export run per tenant.
	"workspace_id" BIGINT NOT NULL,
	-- Uploader. Null once the membership is purged, which keeps the file usable.
	"uploaded_by_member_id" BIGINT,
	-- Message the file was first posted with. Null for a file uploaded to the workspace but not yet shared.
	"message_id" BIGINT,
	-- Original filename, shown in the file list and used on download.
	"filename" VARCHAR(255) NOT NULL,
	-- Object-store URL of the stored bytes.
	"object_url" VARCHAR(500) NOT NULL,
	-- MIME type, which decides whether the client renders a preview.
	"content_type" VARCHAR(120) NOT NULL,
	-- Size in bytes, counted against the workspace storage quota.
	"size_bytes" BIGINT NOT NULL,
	-- True for a link to Drive or Dropbox rather than stored bytes; the object_url then points outward.
	"is_external" BOOLEAN NOT NULL DEFAULT false,
	-- Upload time.
	"uploaded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "files" IS 'A file is a workspace object that a message references, not a child of a message. That is what lets the same upload be reshared into several channels without copying bytes.';
COMMENT ON COLUMN "files"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "files"."workspace_id" IS 'Owning workspace, so retention and export run per tenant.';
COMMENT ON COLUMN "files"."uploaded_by_member_id" IS 'Uploader. Null once the membership is purged, which keeps the file usable.';
COMMENT ON COLUMN "files"."message_id" IS 'Message the file was first posted with. Null for a file uploaded to the workspace but not yet shared.';
COMMENT ON COLUMN "files"."filename" IS 'Original filename, shown in the file list and used on download.';
COMMENT ON COLUMN "files"."object_url" IS 'Object-store URL of the stored bytes.';
COMMENT ON COLUMN "files"."content_type" IS 'MIME type, which decides whether the client renders a preview.';
COMMENT ON COLUMN "files"."size_bytes" IS 'Size in bytes, counted against the workspace storage quota.';
COMMENT ON COLUMN "files"."is_external" IS 'True for a link to Drive or Dropbox rather than stored bytes; the object_url then points outward.';
COMMENT ON COLUMN "files"."uploaded_at" IS 'Upload time.';

CREATE INDEX "idx_files_workspace_uploaded"
ON "files" ("workspace_id", "uploaded_at");
CREATE INDEX "idx_files_message"
ON "files" ("message_id");

CREATE TABLE IF NOT EXISTS "saved_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Whose list this is. Saved items are strictly private.
	"workspace_member_id" BIGINT NOT NULL,
	-- Message saved for later.
	"message_id" BIGINT NOT NULL,
	-- open | completed | archived. A saved item is a personal task, so it has a lifecycle a bookmark does not.
	"state" VARCHAR(16) NOT NULL DEFAULT 'open',
	-- Optional reminder time. Null means no reminder.
	"remind_at" TIMESTAMP,
	-- When it was saved.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When it was ticked off. Null while open.
	"completed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "saved_items" IS 'Per-person bookmarks with a state machine. The unique constraint makes saving the same message twice idempotent.';
COMMENT ON COLUMN "saved_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "saved_items"."workspace_member_id" IS 'Whose list this is. Saved items are strictly private.';
COMMENT ON COLUMN "saved_items"."message_id" IS 'Message saved for later.';
COMMENT ON COLUMN "saved_items"."state" IS 'open | completed | archived. A saved item is a personal task, so it has a lifecycle a bookmark does not.';
COMMENT ON COLUMN "saved_items"."remind_at" IS 'Optional reminder time. Null means no reminder.';
COMMENT ON COLUMN "saved_items"."created_at" IS 'When it was saved.';
COMMENT ON COLUMN "saved_items"."completed_at" IS 'When it was ticked off. Null while open.';

CREATE INDEX "idx_saved_items_member_state"
ON "saved_items" ("workspace_member_id", "state", "created_at");
CREATE UNIQUE INDEX "uq_saved_items_member_message"
ON "saved_items" ("workspace_member_id", "message_id");

CREATE TABLE IF NOT EXISTS "apps" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- App name shown in the directory and next to posted messages.
	"name" VARCHAR(120) NOT NULL,
	-- URL segment in the app directory.
	"slug" VARCHAR(140) NOT NULL UNIQUE,
	-- Publisher shown on the install screen.
	"developer_name" VARCHAR(160),
	-- CDN URL of the app icon.
	"icon_url" VARCHAR(500),
	-- False for a private app built inside one workspace, which is the majority of them.
	"is_directory_listed" BOOLEAN NOT NULL DEFAULT false,
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "apps" IS 'The app definition, global and independent of any install. Scopes live on the install, not here, because two workspaces can grant the same app different access.';
COMMENT ON COLUMN "apps"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "apps"."name" IS 'App name shown in the directory and next to posted messages.';
COMMENT ON COLUMN "apps"."slug" IS 'URL segment in the app directory.';
COMMENT ON COLUMN "apps"."developer_name" IS 'Publisher shown on the install screen.';
COMMENT ON COLUMN "apps"."icon_url" IS 'CDN URL of the app icon.';
COMMENT ON COLUMN "apps"."is_directory_listed" IS 'False for a private app built inside one workspace, which is the majority of them.';
COMMENT ON COLUMN "apps"."created_at" IS 'Row creation time.';

CREATE TABLE IF NOT EXISTS "app_installations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Workspace the app is installed into.
	"workspace_id" BIGINT NOT NULL,
	-- App installed.
	"app_id" BIGINT NOT NULL,
	-- Who authorised it. Null once that membership is gone, which does not revoke the install.
	"installed_by_member_id" BIGINT,
	-- The bot account the app posts as. Null for an app that only receives events.
	"bot_user_id" BIGINT,
	-- Hash of the issued token. The plaintext is shown once and never stored.
	"access_token_hash" VARCHAR(255) NOT NULL,
	-- active | revoked | suspended. Revoked installs are kept so the audit trail survives.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Install time.
	"installed_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When access was withdrawn. Null while active.
	"revoked_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "app_installations" IS 'The grant, one per app per workspace. Everything sensitive - the token and the scopes - hangs off the install rather than the app definition.';
COMMENT ON COLUMN "app_installations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "app_installations"."workspace_id" IS 'Workspace the app is installed into.';
COMMENT ON COLUMN "app_installations"."app_id" IS 'App installed.';
COMMENT ON COLUMN "app_installations"."installed_by_member_id" IS 'Who authorised it. Null once that membership is gone, which does not revoke the install.';
COMMENT ON COLUMN "app_installations"."bot_user_id" IS 'The bot account the app posts as. Null for an app that only receives events.';
COMMENT ON COLUMN "app_installations"."access_token_hash" IS 'Hash of the issued token. The plaintext is shown once and never stored.';
COMMENT ON COLUMN "app_installations"."status" IS 'active | revoked | suspended. Revoked installs are kept so the audit trail survives.';
COMMENT ON COLUMN "app_installations"."installed_at" IS 'Install time.';
COMMENT ON COLUMN "app_installations"."revoked_at" IS 'When access was withdrawn. Null while active.';

CREATE UNIQUE INDEX "uq_app_installations_ws_app"
ON "app_installations" ("workspace_id", "app_id");

CREATE TABLE IF NOT EXISTS "app_installation_scopes" (
	-- Install the scope was granted to, part of the composite key.
	"installation_id" BIGINT,
	-- Granted scope such as channels:read or chat:write, part of the key. One row per scope, so a re-consent is a diff rather than a rewrite.
	"scope" VARCHAR(80),
	-- When this particular scope was granted, which is how you prove when an app gained a capability.
	"granted_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("installation_id", "scope")
);

COMMENT ON TABLE "app_installation_scopes" IS 'Scopes as rows, not a delimited string. This is what makes "which apps can read private channels?" an indexed query when a security review asks.';
COMMENT ON COLUMN "app_installation_scopes"."installation_id" IS 'Install the scope was granted to, part of the composite key.';
COMMENT ON COLUMN "app_installation_scopes"."scope" IS 'Granted scope such as channels:read or chat:write, part of the key. One row per scope, so a re-consent is a diff rather than a rewrite.';
COMMENT ON COLUMN "app_installation_scopes"."granted_at" IS 'When this particular scope was granted, which is how you prove when an app gained a capability.';

CREATE INDEX "idx_app_installation_scopes_scope"
ON "app_installation_scopes" ("scope");

ALTER TABLE "workspaces"
ADD FOREIGN KEY("default_channel_id") REFERENCES "channels"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "workspace_members"
ADD FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "workspace_members"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
